// Small, locally synthesized sounds: no downloads, trackers or paid audio services.
export class Sound {
 constructor(){this.context=null;this.enabled=true;try{this.enabled=localStorage.getItem('moka-sound')!=='off';}catch{}this.nodes=new Set();}
 unlock(){if(!this.enabled)return;try{this.context??=new (window.AudioContext||window.webkitAudioContext)();if(this.context.state==='suspended')this.context.resume().catch(()=>{});}catch{}}
 toggle(){this.enabled=!this.enabled;try{localStorage.setItem('moka-sound',this.enabled?'on':'off');}catch{}if(!this.enabled)this.stop();else{this.unlock();this.play('click');}return this.enabled;}
 stop(){for(const n of this.nodes){try{n.stop();}catch{}}this.nodes.clear();}
 tone(freq,start,duration=.15,volume=.045,type='sine'){const c=this.context;if(!c||c.state!=='running')return;const o=c.createOscillator(),g=c.createGain(),at=c.currentTime+start;o.type=type;o.frequency.setValueAtTime(freq,at);g.gain.setValueAtTime(0,at);g.gain.linearRampToValueAtTime(volume,at+.012);g.gain.exponentialRampToValueAtTime(.0001,at+duration);o.connect(g);g.connect(c.destination);this.nodes.add(o);o.onended=()=>{this.nodes.delete(o);o.disconnect();g.disconnect();};o.start(at);o.stop(at+duration+.02);}
 noise(duration=.7,frequency=900){const c=this.context;if(!c||c.state!=='running')return;const n=c.createBufferSource(),b=c.createBuffer(1,Math.floor(c.sampleRate*duration),c.sampleRate),data=b.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*.12;const filter=c.createBiquadFilter(),gain=c.createGain();filter.type='bandpass';filter.frequency.value=frequency;filter.Q.value=.6;n.buffer=b;n.connect(filter);filter.connect(gain);gain.connect(c.destination);gain.gain.setValueAtTime(0,c.currentTime);gain.gain.linearRampToValueAtTime(.18,c.currentTime+.08);gain.gain.exponentialRampToValueAtTime(.001,c.currentTime+duration);this.nodes.add(n);n.onended=()=>{this.nodes.delete(n);n.disconnect();filter.disconnect();gain.disconnect();};n.start();n.stop(c.currentTime+duration);}
 play(kind){if(!this.enabled)return;this.unlock();if(kind==='click')this.tone(660,0,.09,.025);if(kind==='step'){this.tone(523,0);this.tone(784,.09,.22);}if(kind==='timer'){[784,988,1175,988].forEach((f,i)=>this.tone(f,i*.18,.35,.065));}if(kind==='finish'){[523,659,784,1047].forEach((f,i)=>this.tone(f,i*.13,.5,.055));}}
 action(kind){if(!this.enabled)return;this.unlock();if(['grind','froth'].includes(kind))this.noise(.65,kind==='grind'?650:1300);if(['water','bloom','drip','pourCoffee','pourMilk'].includes(kind)){this.noise(.75,1900);[800,670,920].forEach((f,i)=>this.tone(f,.12+i*.16,.08,.012));}if(['ice','assemble','basket','filter'].includes(kind))[1320,1760].forEach((f,i)=>this.tone(f,i*.12,.2,.023));}
}
